<script setup lang="ts">
import {useI18n} from 'vue-i18n'
import {settlementAmount} from '../supplemental'
import type {SettlementRecord} from '../supplemental'
defineProps<{record:SettlementRecord}>()
const {locale}=useI18n(),en=()=>locale.value.startsWith('en'),x=(z:string,e:string)=>en()?e:z,money=(v:string|null|undefined)=>settlementAmount(v,en())
const state=(v:string)=>({actual:x('实际','Actual'),forecast:x('预测','Forecast'),'known-zero':x('有凭证零值','Evidenced zero'),unknown:x('未知','Unknown')}[v]||v)
</script>
<template><section class="wf-section" data-testid="settlement-snapshot"><h3>{{x('该次责任结算冻结来源（只读）','Frozen sources for this liability settlement (read only)')}}</h3><p>{{x('结算记录／结算月份／记录时间','Settlement record / settlement month / recorded at')}}: {{record.id}} / {{record.settlementMonth}} / {{record.recordedAt??x('未知','Unknown')}}</p><p v-if="record.reconciliationId">{{x('原不可变AW复核','Original immutable AW reconciliation')}}: {{record.reconciliationId}}</p><template v-if="record.context"><p class="wf-hint">{{x('以下为该次结算响应中保存的原始年度来源；后续读取或修改当前资料不会替换此快照。','These annual sources were retained in this settlement response. Later reads or changes to current facts do not replace this snapshot.')}}</p><dl class="wf-details"><dt>{{x('公司／员工／原年度','Company / employee / original year')}}</dt><dd>{{record.context.companyId}} / {{record.context.employeeId}} / {{record.context.year}}</dd><dt>{{x('来源修订／指纹','Source revision / fingerprint')}}</dt><dd>{{record.context.version}} / {{record.context.fingerprint}}</dd></dl><div class="wf-table-wrap"><table><thead><tr><th>{{x('原月份／事实状态','Original month / fact state')}}</th><th>{{x('原始OW／CPF OW','Raw OW / CPF OW')}}</th><th>{{x('原员工／雇主已确认责任','Recognised employee / employer liability')}}</th><th>{{x('原政策名称／版本','Original policy / revision')}}</th><th>{{x('原来源','Original source')}}</th></tr></thead><tbody><tr v-for="m in record.context.months" :key="m.month"><td>{{m.month}} / {{state(m.state)}}</td><td>{{money(m.rawOW)}} / {{money(m.cpfOW)}}</td><td>{{money(m.recognisedEmployeeCpf)}} / {{money(m.recognisedEmployerCpf)}}</td><td>{{m.policy?.name??x('未知','Unknown')}} / {{m.policy?.version??x('未知','Unknown')}}</td><td>{{m.source}}</td></tr></tbody></table></div><p v-for="(code,i) in record.context.issues" :key="i" class="wf-issue">{{code}}</p><details><summary>{{x('查看完整冻结来源与原政策／身份凭证','View complete frozen sources, original policies and identity evidence')}}</summary><pre>{{JSON.stringify(record.context,null,2)}}</pre></details></template><p v-else class="wf-hint">{{x('该历史结算未保存年度来源快照；当前年度资料不会替代原快照。','This historical settlement has no retained annual source snapshot. Current annual data will not replace it.')}}</p></section></template>
<style scoped>p,dd,td,pre{overflow-wrap:anywhere}pre{white-space:pre-wrap;max-height:32rem;overflow:auto}</style>
